export function validateST_SecondPieSizePercent(value: unknown, path = 'ST_SecondPieSizePercent'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (typeof value !== 'string') issues.push(issue(path, 'invalid-value', 'expected a string'));
  if (typeof value === 'string' && !(new RegExp("0*(([5-9])|([1-9][0-9])|(1[0-9][0-9])|200)%")).test(value)) issues.push(issue(path, 'facet-violation', 'pattern mismatch'));
  return issues;
}

