export function validateCT_Area3DChart(value: unknown, path = 'CT_Area3DChart'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['grouping'] === undefined) {
  } else {
    issues.push(...validateCT_Grouping(v['grouping'], path + '.grouping'));
  }
  if (v['varyColors'] === undefined) {
  } else {
    issues.push(...validateCT_Boolean(v['varyColors'], path + '.varyColors'));
  }
  if (!Array.isArray(v['ser'])) {
  } else {
    for (let i = 0; i < (v['ser'] as readonly unknown[]).length; i += 1) {
      issues.push(...validateCT_AreaSer((v['ser'] as readonly unknown[])[i], path + '.ser[' + i + ']'));
    }
  }
  if (v['dLbls'] === undefined) {
  } else {
    issues.push(...validateCT_DLbls(v['dLbls'], path + '.dLbls'));
  }
  if (v['dropLines'] === undefined) {
  } else {
    issues.push(...validateCT_ChartLines(v['dropLines'], path + '.dropLines'));
  }
  if (v['gapDepth'] === undefined) {
  } else {
    issues.push(...validateCT_GapAmount(v['gapDepth'], path + '.gapDepth'));
  }
  if (!Array.isArray(v['axId'])) {
  } else {
    for (let i = 0; i < (v['axId'] as readonly unknown[]).length; i += 1) {
      issues.push(...validateCT_UnsignedInt((v['axId'] as readonly unknown[])[i], path + '.axId[' + i + ']'));
    }
  }
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionList(v['extLst'], path + '.extLst'));
  }
  return issues;
}

