export function validateCT_AxDataSource(value: unknown, path = 'CT_AxDataSource'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['content'] === undefined) {
    issues.push(issue(path + '.content', 'missing-required', 'required slot is absent'));
  } else {
    if (v['content'] && typeof v['content'] === 'object') {
      const item = v['content'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'multiLvlStrRef') issues.push(...validateCT_MultiLvlStrRef(item.value, path + '.content' + '.value'));
        if (item.kind === 'numRef') issues.push(...validateCT_NumRef(item.value, path + '.content' + '.value'));
        if (item.kind === 'numLit') issues.push(...validateCT_NumData(item.value, path + '.content' + '.value'));
        if (item.kind === 'strRef') issues.push(...validateCT_StrRef(item.value, path + '.content' + '.value'));
        if (item.kind === 'strLit') issues.push(...validateCT_StrData(item.value, path + '.content' + '.value'));
        if ('multiLvlStrRef' !== item.kind && 'numRef' !== item.kind && 'numLit' !== item.kind && 'strRef' !== item.kind && 'strLit' !== item.kind) issues.push(issue(path + '.content', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  return issues;
}

